def missing_number(nums):
    acc = len(nums)                    # the index n has no slot
    for i, x in enumerate(nums):
        acc ^= i ^ x                   # pairs cancel, the missing one remains
    return acc

P09-first-missing-positive:
def first_missing_positive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1            # value v belongs in slot v-1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

