def first_missing_positive(nums):
    n = len(nums)
    for i in range(n):
        if not 1 <= nums[i] <= n:
            nums[i] = n + 1                   # can never be the answer
    for x in nums:
        v = abs(x)
        if v <= n:
            nums[v - 1] = -abs(nums[v - 1])   # sign of slot v-1 says "v is here"
    for i in range(n):
        if nums[i] > 0:
            return i + 1
    return n + 1
